if (Inputs.real === undefined) return;
const real = String(Inputs.real || '');
const given = String(Inputs.given || '');
if (real.length < 8) {
  Outputs.message = 'The household key is not set up yet: a grown-up writes one (8 characters or more) in the app\'s .env file.';
  Outputs.wrong();
  return;
}
let diff = real.length ^ given.length;
for (let i = 0; i < real.length; i++) diff |= real.charCodeAt(i) ^ given.charCodeAt(i % Math.max(1, given.length));
if (diff !== 0) {
  await new Promise((resolve) => setTimeout(resolve, 2000));
  Outputs.message = 'That is not the household key.';
  Outputs.wrong();
  return;
}
Outputs.match();
